INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504424-fin460', 'stk-user9840', 'FIN 460', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-460-derivatives/180800/1", "user": "user9840", "ts": 1546441816000, "tid": 180800, "pn": 1}}', 1546441816000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
